import React from "react";
import Navbar from "../components/Navbar";
import Footer from "../components/Footer";
import "./PageShell.css";

export default function About() {
  return (
    <div>
      <Navbar />
      <div className="page">
        <h1>About Us</h1>
        <p>
          Hanuman Healthcare was founded with the motto "Excellence through Innovation."
          Across our four verticals — Public Infrastructure, Healthcare, Technology and
          Agro — we work towards building a strong, reliable and ethical institution that
          will serve humanity for decades and centuries to come.
        </p>
        <p>
          As of date we have a market presence across the Indian Subcontinent, and our
          management plans to expand into the GCC and Western European markets in the
          coming decade. This is a step forward towards our mission of global outreach:
          providing institutions and individuals with innovative, cost-effective and
          eco-friendly solutions that are practical, affordable and sustainable.
        </p>
      </div>
      <Footer />
    </div>
  );
}
